//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.resoroomId;
scwin.fileRowcount;
scwin.mvFileExist = 'N';
scwin.vScrenID = "ULDSTF30305.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    //IR자료실 개별조회
    trs_Read.Action = "/IRMgt.do?method=readIRDataRoom&resoroomId=" + scwin.resoroomId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_irDataRoomSingle,O:pOutput2=dts_fileData,O:pOutput3=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_update = function() {
    //IR자료실 수정
    if (txb_isur_cd.getValue() == "" || txb_isur_cd.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (title.getValue() == "" || title.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }

    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
    if( koreng_tp_cd.CodeValue == '1') {
    	txb_irhlddate.Text = "";
    }
    */

    /*
    // 동영상 필수 제거 : 2008.10.22
    if(mv_attach_file_nm.value == "" || mv_attach_file_nm.value.indexOf(" ") == "" ) {
    	alert("[동영상 파일은] 반드시 첨부하셔야합니다.");
    	mv_attach_file_nm.focus();
    	return;
    }
    */

    // 동영상이 없으면 첨부파일은 있어야함.
    if (mv_attach_file_nm.getValue() == "" || mv_attach_file_nm.getValue().indexOf(" ") == "") {
        var fileCnt = dts_fileList.getTotalRow();
        if (fileCnt <= 0) {
            $c.win.alert("[동영상 파일 또는 첨부파일]은 반드시 첨부하셔야합니다.");
            mv_attach_file_nm.focus();
            return;
        }
    }
    if (content.text == "" || content.text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(content, 200, "내용")) {
        content.text = "";
        content.focus();
        return false;
    }
    if (cast_yn.getValue() == 'Y' & submit_yn.getValue() == 'N') {
        //상장법인제출여부가 Y가 아니면 공개여부를 Y로 설정할 수 없음
        $c.win.alert("[상장법인 제출여부] 가 Y일 경우에만 [공개여부]를 YES로 설정 가능합니다.");
        cast_yn.focus();
        cast_yn.setValue('N');
        return;
    }
    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        /*
        if(dts_fileDataUpdate.NameString(dts_fileDataUpdate.RowPosition,"fileInfo") == "") {
        //alert("Reset=Y");
        	dts_fileDataUpdate.Reset();
        }

        trs_Update.Action="/IRMgt.do?method=modifyIRDataRoom&resoroom_id="+resoroomId;
        trs_Update.KeyName="toinb_dataid4";
        trs_Update.KeyValue="JSP(I:pInput1=dts_irDataRoomSingle,I:pInput2=dts_fileDataUpdate,I:pInput3=dts_fileList)";			
        trs_Update.Post();	
        */

        trs_Update.Action = "/IRMgt.do?method=modifyIRDataRoom&resoroom_id=" + scwin.resoroomId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput1=dts_irDataRoomSingle,I:pInput2=dts_fileData,I:pInput3=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    //IR자료실 등록
    /* 파일업로드 */
    if (txb_isur_cd.getValue() == "" || txb_isur_cd.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (title.getValue() == "" || title.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }

    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
    if( koreng_tp_cd.CodeValue == '1') {
    	txb_irhlddate.Text = "";
    }
    */

    /*
    // 동영상 필수 제거 : 2008.10.22		
    if(mv_attach_file_nm.value == "" || mv_attach_file_nm.value.indexOf(" ") == "" ) {
    	alert("[동영상 파일은] 반드시 첨부하셔야합니다.");
    	mv_attach_file_nm.focus();
    	return;
    }
    */

    // 동영상이 없으면 첨부파일은 있어야함.
    if (mv_attach_file_nm.getValue() == "" || mv_attach_file_nm.getValue().indexOf(" ") == "") {
        var fileCnt = dts_fileList.getTotalRow();
        if (fileCnt <= 0) {
            $c.win.alert("[동영상 파일 또는 첨부파일]은 반드시 첨부하셔야합니다.");
            mv_attach_file_nm.focus();
            return;
        }
    }
    if (content.text == "" || content.text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(content, 200, "내용")) {
        content.text = "";
        content.focus();
        return false;
    }
    var rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        usr_id.setValue(js_id);
        trs_Save.Action = "/IRMgt.do?method=registerIRDataRoom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_irDataSaveInfo,I:pFile1=dts_fileData,I:pFile2=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    //IR자료실 삭제
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_irDataRoomSingle.insertRow();
        dts_irDataRoomSingle.setCellData(2, "RESOROOM_ID", dts_irDataRoomSingle.getCellData(1, "RESOROOM_ID"));
        dts_irDataRoomSingle.setCellData(2, "KORENG_TP_CD", dts_irDataRoomSingle.getCellData(1, "KORENG_TP_CD"));
        trs_Delete.Action = "/IRMgt.do?method=removeIRDataRoom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyName = "toinb_dataid4";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_irDataRoomSingle)";
        trs_Delete.Post();
    }
};
scwin.fn_SetIrInfoHeader = function() {
    // CUD용 Header
    dts_irDataSaveInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_INSERT_IRINFO_INOUT";
    dts_irDataSaveInfo.Reset();
    dts_irDataSaveInfo.insertRow();
};
scwin.fn_SetIrDataHeader = function() {
    // CUD용 Header
    dts_irDataSaveData.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_INSERT_IRDATA_INOUT";
    dts_irDataSaveData.Reset();
    dts_irDataSaveData.AddRow();
};

//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.resoroomId + "&attach_seq=" + attach_seq + "&gubun=1";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_ChangeMovie = function() {
    //	location.href = "/IRMgt.do?method=changeMovie&resoroomId="+resoroomId;
    location.href = "/bizspt/JLDSTF30305.jsp?resoroomId=" + scwin.resoroomId;

};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.moveData_OnClick = function() {
    var mv_filenm = mv_attach_file_nm.getValue();
    if (scwin.resoroomId == 'input') {
        dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.getValue());
    } else {
        /*	
		if (mvFileExist  == 'Y') {
dts_fileDataUpdate.setNameValue(dts_fileDataUpdate.rowposition, "fileInfo",moveData.Value) ;
		} else {
dts_fileData.setNameValue(dts_fileData.rowposition, "fileInfo",moveData.Value) ;
		}
		*/
        dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.getValue());
    }
    mv_attach_file_nm.setValue(moveData.getValue());
    if (moveData.getValue() == "") {
        mv_attach_file_nm.setValue(mv_filenm);
    }
};
scwin.trs_Read_OnSuccess = function() {

};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "IR자료수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "IR자료수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "IR자료등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "IR자료등록"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.save_onclick = function() {
    if (scwin.resoroomId != "input") {
        scwin.fn_update();
    } else {
        scwin.fn_save();
    }
};
scwin.delete_onclick = function() {
    scwin.fn_delete();
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "IR자료삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "IR자료삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_lineadd_onclick = function() {
    if (scwin.resoroomId != "input") {
        scwin.fileRowcount = dts_fileList.getTotalRow();
    }
    scwin.fileRowcount++;
    if (scwin.fileRowcount >= 3) {
        $c.win.alert("더이상 추가하실수 없습니다.");
        scwin.fileRowcount = 3;
    } else {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
        } else {
            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        }
    }
};
scwin.btn_linedelete_onclick = function() {
    if (scwin.fileRowcount > 0) scwin.fileRowcount--;
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.mv_attach_file_nm_onclick = function() {
    if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileData.getCellData(1, "ATTACH_SEQ"));
    }
};
scwin.grd_userlist_OnClick = function(row, colid) {
    // 2009-03-11
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.change_movie_onclick = function() {
    scwin.fn_ChangeMovie();
};
scwin.icn_SCal_onclick = function() {
    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
    if(koreng_tp_cd.CodeValue == '1') {
    	alert("영문일때만 입력 가능합니다.");
    } else {
    	popUpCalendar2(txb_irhlddate);
    }*/
    popUpCalendar2(txb_irhlddate);
};
scwin.koreng_tp_cd_OnClick = function() {
    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ

    /*
    if(koreng_tp_cd.CodeValue == '1') {
    	txb_irhlddate.ReadOnly = "true";
    } else {
    	txb_irhlddate.ReadOnly = "false";
    }*/
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    reId = $c.frame.path("../").fn_getId;
    scwin.resoroomId = reId();
    //수정화면 onload
    if (scwin.resoroomId != "input") {
        scwin.fn_single_read();
        mv_attach_file_nm.setReadOnly(true);
        if (dts_fileData.getTotalRow() == 0 || dts_fileData.getCellData(1, "PIC_YN") == '') {

            //dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            dts_fileData.insertRow();
        }

        // 2009-03-26
        if (js_id != "999999") change_movie.style.display = 'none';

        // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
        /*
        if(koreng_tp_cd.CodeValue == '1') {
        	txb_irhlddate.ReadOnly = "true";
        } else {
        	txb_irhlddate.ReadOnly = "false";
        }
        */
        cast_yn.setValue('Y');
    } else {
        //등록화면 onload
        scwin.fn_SetIrInfoHeader();
        //dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileData.insertRow();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        cast_yn.setValue("Y");
        scwin.fileRowcount = 0;
        edt_Date.setValue($c.ut.cGetToday("yyyymmdd"));
        usr_id.setValue(js_emp_nm);
        // 2009-03-18
        change_movie.style.display = 'none';
        label_14.style.display = 'none';
        koreng_tp_cd.setValue('1'); //디폴트 국문으로 셋팅.		
        //txb_irhlddate.ReadOnly = "true"; // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ

    }
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    cast_yn.setValue('Y');
};
